-- AMBIGUOUS (reading A): patients "on a statin" = distinct patients with a statin pickup (pharmacy_dispenses status 'dispensed'; simva/atorva/rosuva/prava/lova/pitava/fluvastatin) dated in the 12 months to the as-of date, 2029-05-28..2030-05-27. Reading B (undated legacy medication_lists entry naming a statin) gives a different count.
SELECT COUNT(DISTINCT patient) AS count FROM records WHERE stream='pharmacy_dispenses' AND json_extract(payload,'$.status')='dispensed'
  AND json_extract(payload,'$.event_date') BETWEEN '2029-05-28' AND '2030-05-27' AND (lower(json_extract(payload,'$.medication_name')) LIKE '%simvastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%atorvastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%rosuvastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%pravastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%lovastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%pitavastatin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%fluvastatin%');
